python -c "
import win32com.client
sw = win32com.client.Dispatch('SldWorks.Application')
# RevisionNumber is a method that returns string
try:
    rev = sw.RevisionNumber
    print(f'REV_PROP={rev}')
except: pass

try:
    pid = sw.GetProcessID()
    print(f'PID={pid}')
except Exception as e:
    print(f'PID_ERR={e}')

try:
    vis = sw.Visible
    print(f'VISIBLE={vis}')
except Exception as e:
    print(f'VIS_ERR={e}')

try:
    dc = sw.GetDocumentCount()
    print(f'DOC_COUNT={dc}')
except Exception as e:
    print(f'DOC_ERR={e}')

try:
    # Try getting active doc
    doc = sw.ActiveDoc
    if doc:
        print(f'ACTIVE_DOC={doc.GetTitle()}')
    else:
        print('ACTIVE_DOC=None')
except Exception as e:
    print(f'ACTIVEDOC_ERR={e}')
"

